        final version = decoded[agentName];
        return version is String ? version : null;
      }
    } on FormatException {
      return null;
    }
    return null;
  }

  /// Best-effort source commit: `git rev-parse HEAD` in the agent root.
  String _detectSourceCommit(String agentRoot) {
