  void _wireAsyncPool(
    QuickjsRuntime rt, {
    required String scriptPath,
    required Map<String, dynamic> jobParams,
    required Map<String, dynamic>? ticket,
    required String? workingDirectory,
    required JsRunConfig cfg,
