    jsonEncode({
      'jobId': jobId,
      'fnSource': fnSource,
      'argsJson': argsJson,
      'context': context ??
          (_dispatchContext != null
              ? _dispatchContext()
              : const <String, dynamic>{}),
    }),
  );
