}) {
  if (!_booted) {
    throw StateError('JS worker pool is not booted');
  }
  final worker = _acquireWorker();
  final jobId = _nextJobId++;
  _jobs[jobId] = _PendingJob(workerId: worker.id);
  worker.sendPort.send(
    jsonEncode({
      'jobId': jobId,
      'fnSource': fnSource,
      'argsJson': argsJson,
      'context': context ??
          (_dispatchContext != null
              ? _dispatchContext()
              : const <String, dynamic>{}),
    }),
  );
  return jobId;
}

